<template>
  <aside class="detail">
    <header class="detail-header"><span>知识详情</span><span class="detail-marker">INSPECTOR</span></header>
    <div v-if="!entity && !relation" class="empty-detail"><div class="inspect-icon">⌕</div><h3>查看知识与证据</h3><p>点击图中的实体或关联线，<br />在这里了解详细信息。</p></div>
    <div v-else class="detail-body">
      <div class="detail-category"><span class="category-dot"></span>{{ entity ? entityLabel(entity.label) : '关系记录' }}</div>
      <h3>{{ entity?.name || (relation && relationLabel(relation.type)) }}</h3>
      <p v-if="relation" class="endpoints">{{ endpoints }}</p>
      <p v-if="entity" class="aliases">{{ entity.aliases.filter(a=>a!==entity?.name).join(' · ') || entity.legacy_id }}</p>
      <el-button v-if="entity" class="expand-button" @click="$emit('expand', entity.id)">展开关联 <span>↗</span></el-button>
      <section v-if="entity?.label === 'ClinicalEntry'" class="record-summary"><h4>完整知识记录</h4><p>{{ entity.properties.summary }}</p></section>
      <section v-if="relation?.properties.summary" class="record-summary"><h4>完整知识记录</h4><p>{{ relation.properties.summary }}</p></section>
      <section v-if="records.length" class="knowledge-records"><h4>知识记录 · {{ records.length }} 条</h4><details v-for="record in records" :key="record.id" class="knowledge-record"><summary>{{ record.title }}</summary><p>{{ record.subject_name }}<span v-if="record.related_name"> · {{ record.related_name }}</span></p><div v-for="(proof,index) in record.evidence" :key="index"><p>{{ proof.scope_conditions }}</p><a v-if="safeSource(sourceUrl(proof.source_id))" :href="safeSource(sourceUrl(proof.source_id))" target="_blank" rel="noopener noreferrer">{{ proof.source_title || '查看原文' }} ↗</a><p>原文定位：{{ format(proof.locator) }}</p></div><details class="technical-record"><summary>查看适用条件与参数</summary><pre>{{ format(record.context) }}</pre></details></details></section>
      <section v-if="relation?.evidence" class="scoped-evidence"><span class="evidence-badge">原文已核对<span v-if="relation.evidence.region==='US'"> · 美国补充</span></span><h4>证据摘要</h4><p>{{ relation.evidence.summary }}</p><h4>适用条件</h4><p>{{ relation.evidence.conditions }}</p><h4>处理提示</h4><p>{{ relation.evidence.action }}</p><small>{{ relation.evidence.population }}<br/>{{ relation.evidence.formulation }}</small></section>
      <details v-if="Object.keys(detailProperties(entity || relation)).length" class="attributes"><summary>结构化字段（适用范围见来源）</summary><dl><template v-for="(value, key) in detailProperties(entity || relation)" :key="key"><dt>{{ propertyLabel(String(key)) }}</dt><dd>{{ value }}</dd></template></dl></details>
      <section class="evidence"><div class="section-heading"><h4>来源与证据</h4><span>{{ sources.length }} 条记录</span></div><div class="review-note"><i></i><div>{{ sources.some(s=>s.review_status==='source_checked_by_agent') ? '含已核对原文的记录' : '医学原文待核实' }}<small>逐条查看来源、适用条件与核对状态。</small></div></div>
        <details v-for="(source,index) in sources" :key="source.id" class="source-card"><summary><span class="source-index">{{ String(index+1).padStart(2,'0') }}</span><span class="source-name">{{ source.title || sourceName(source.file) }}<small>{{ source.review_status==='source_checked_by_agent' ? '原文已核对' : '仓库示例 · 未核实' }}</small></span><span class="source-arrow">⌄</span></summary><div class="source-content"><template v-if="source.title"><p>{{ source.publisher }} · {{ source.region==='US' ? '美国标签补充' : source.region==='CN' ? '中国说明书' : source.region==='UK' ? '英国资料' : source.region==='WHO' ? 'WHO分类资料' : '原始研究资料' }}</p><p>修订 {{ source.label_revision }} · PDF第 {{ source.pages?.join('、') }} 页</p><p>{{ source.formulation }}</p><a v-if="safeSource(source.url)" :href="safeSource(source.url)+'#page='+(source.pages?.[0] || 1)" target="_blank" rel="noopener noreferrer">查看原始说明书 ↗</a></template><p>{{ source.file }} {{ source.pointer }}</p><details class="technical-record"><summary>查看结构化记录</summary><pre>{{ JSON.stringify(source.original,null,2) }}</pre></details></div></details><p v-if="!sources.length" class="no-source">此记录没有逐条来源信息。</p>
      </section>
      <p v-if="relation" class="technical-type">关系标识 <code>{{ relation.type }}</code></p>
    </div>
  </aside>
</template>
<script setup lang="ts">
import { computed } from 'vue'
import type { Entity, Relation, Source } from '@/types/knowledgeGraph'
import type { CandidateRecord } from '@/api/candidateGraph'
import { entityLabel, relationLabel } from './labels'
const props=defineProps<{entity: Entity | null; relation: Relation | null; sources: Source[]; endpoints: string}>()
defineEmits<{expand: [id: string]}>()
function safeSource(url?:string){try{const u=new URL(url || '');return u.protocol==='https:' ? u.href : ''}catch{return ''}}
const records=computed(() => ((props.entity || props.relation)?.properties.records || []) as CandidateRecord[])
function sourceUrl(id:string) { return props.sources.find(s => s.id===id)?.url }
function format(value:unknown) { return typeof value === 'string' ? value : JSON.stringify(value,null,2) }
function detailProperties(item: Entity | Relation | null) { return Object.fromEntries(Object.entries(item?.properties || {}).filter(([key]) => !['records','summary','subject_name','subject_id','related_name','owner_label'].includes(key))) }
const propertyNames: Record<string,string> = {name:'中文名称',name_cn:'中文名称',generic_name:'英文通用名',category:'药物类别',class:'类别',drug_class:'药物类别',dose_start:'起始剂量（原记录）',dose_max:'最大剂量（原记录）',dose_range:'剂量范围（原记录）',description:'描述',guideline_source:'来源说明',is_first_line_for_OCD:'强迫症一线标记（原记录）'}
function propertyLabel(key:string){return propertyNames[key] || key}
function sourceName(file:string){return ({'china_guidelines.json':'指南示例资料','psychiatric_drugs.json':'药物示例资料','icd11_depression.json':'抑郁相关示例','icd11_schizophrenia.json':'精神分裂症相关示例','symptom_synonyms.json':'症状别名资料'} as Record<string,string>)[file.split('/').pop() || ''] || '仓库来源记录'}
</script>
<style scoped>
.knowledge-record{border:1px solid #e1e9ef;border-radius:8px;margin-top:10px;padding:10px}.knowledge-record>summary{font-size:12px;line-height:1.8;color:#425c68;cursor:pointer}.knowledge-record p,.knowledge-record a{font-size:11px;line-height:1.8;overflow-wrap:anywhere}.knowledge-record p{color:#71848e;margin:10px 0}.knowledge-record a{color:#2e8276}.knowledge-record pre{white-space:pre-wrap;font-size:10px;color:#71848e}
.attributes{margin-top:20px}.attributes summary,.technical-record summary{font-size:10px;color:#81949d;cursor:pointer;margin:10px 0}.record-summary{margin-top:22px;border-left:2px solid #91a6c9;padding-left:12px}.record-summary p{font-size:12px;line-height:1.8;color:#425c68;margin:0}.scoped-evidence p{font-size:11px;line-height:1.9;color:#536e79}.scoped-evidence small{font-size:10px;color:#91a0a9;line-height:1.8}.scoped-evidence h4{margin-top:15px;margin-bottom:5px}.evidence-badge{display:block;font-size:10px;color:#6d8c64;background:#edf5e9;padding:8px;border-radius:6px;line-height:1.6}.source-content a{font-size:11px;color:#2e8276;display:inline-block;margin:5px 0 12px}
.detail{min-width:0;background:#fff;border:1px solid #e1e9ec;border-radius:16px;overflow:hidden;box-shadow:0 4px 20px #254d5908;max-height:635px;display:flex;flex-direction:column;overflow-wrap:anywhere}.detail-header{display:flex;align-items:center;justify-content:space-between;padding:21px 20px 20px;border-bottom:1px solid #edf1f3;font-size:12px;font-weight:600;color:#425d6a}.detail-marker{font-size:8px;font-weight:500;letter-spacing:1.5px;color:#a5b1b8}.detail-body{padding:23px 20px;overflow:auto}.detail-category{display:flex;align-items:center;gap:6px;color:#8b9ba4;font-size:10px}.category-dot{width:5px;height:5px;background:#63a89d;border-radius:50%}.detail h3{font-size:22px;font-weight:600;color:#2f4d5a;margin:10px 0 9px;line-height:1.5}.aliases,.endpoints{font-size:11px;line-height:1.8;color:#91a0a9;margin:0}.endpoints{color:#68818c}.expand-button{width:100%;margin-top:20px;background:#eff6f5;border:1px solid #d4e7e2;color:#33766d;font-size:11px;border-radius:8px;height:35px}.expand-button span{margin-left:12px;font-size:15px}section{margin-top:25px}h4{font-size:11px;color:#6b818d;font-weight:500;margin:0 0 13px;letter-spacing:.4px}.attributes dl{margin:0;display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:11px 8px;font-size:11px;line-height:1.7}.attributes dt{color:#94a3ab;font-size:10px}.attributes dd{margin:0;color:#4e6874;text-align:right}.section-heading{display:flex;justify-content:space-between;align-items:center}.section-heading span{font-size:9px;color:#a1aeb5;margin-bottom:13px}.review-note{display:flex;align-items:flex-start;gap:8px;border-radius:8px;background:#fbf8f1;padding:11px;color:#a28d64;font-size:10px;line-height:1.6}.review-note i{width:4px;height:4px;margin-top:6px;border-radius:50%;background:#c1ad82;flex-shrink:0}.review-note small{display:block;font-size:9px;color:#b3a68c;margin-top:2px}.source-card{border:1px solid #e7edef;border-radius:8px;margin-top:10px;overflow:hidden}.source-card summary{list-style:none;cursor:pointer;display:flex;align-items:center;gap:10px;padding:12px 10px}.source-index{height:25px;width:25px;border-radius:6px;background:#f0f5f7;color:#8ba0aa;display:grid;place-items:center;flex-shrink:0;font-size:9px}.source-name{font-size:11px;color:#607a87;line-height:1.5}.source-name small{display:block;color:#a6b2b9;font-size:9px;margin-top:3px}.source-arrow{margin-left:auto;color:#99aab3;font-size:12px}.source-card[open] .source-arrow{transform:rotate(180deg)}.source-content{background:#f8fafb;border-top:1px solid #edf1f3;padding:10px}.source-content p{font-size:9px;color:#96a6ae;margin:0 0 8px}.source-content pre{white-space:pre-wrap;font-size:10px;line-height:1.8;color:#6e8490;margin:0}.no-source{font-size:11px;color:#a0adb4}.technical-type{font-size:9px;color:#a8b4bb;margin-top:23px}.technical-type code{display:block;margin-top:6px;font-size:9px;color:#8a9ea9}.empty-detail{display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;flex:1;min-height:280px;padding:30px 20px}.inspect-icon{height:46px;width:46px;display:grid;place-items:center;background:#f2f6f8;border:1px solid #e5ecef;border-radius:12px;font-size:24px;color:#94acb5}.empty-detail h3{font-size:13px;font-weight:500;color:#718a95;margin-top:20px}.empty-detail p{font-size:11px;line-height:1.9;color:#a0afb7}
@media(max-width:1050px){.detail{max-height:none}.detail-body{padding:20px}.attributes dl{grid-template-columns:minmax(0,1fr) minmax(0,2fr)}.empty-detail{min-height:180px}}
</style>
